COUNTER_SRC = '"""Streaming per-subroutine Toffoli accounting for kickmix .kmx text circuits.\n\nReads a .kmx file line by line (constant memory apart from the tallies) and\nattributes every Toffoli-like gate (CCX, CCZ, CSWAP) to the stack of\n`INFO_TAG "@enter:<name>"` / `"@exit:<name>"` marks that encloses it. kickmix\nemits such marks for its own arithmetic (gf_mul, c_gf_mul, gf_inverse_chain,\ngf_div, ...) and `CircuitBuilder.mark(...)` emits them for user code.\n\nIt also tracks the classical condition stack (`PUSH_CONDITION if bK` /\n`POP_CONDITION`, plus inline `... if bK`) so that conditioned Toffolis can be\nreported separately, together with how each condition bit was last defined\n(the BIT_STORE1 sources since its last BIT_STORE0, or an HMR measurement).\nThat is what is needed to turn static counts into expected per-shot counts.\n\nUsage:\n    python src/kmx_tag_count.py circuit.kmx out.json\n"""\n\nfrom __future__ import annotations\n\nimport collections\nimport json\nimport sys\n\nTOFFOLI_LIKE = {\'CCX\': 3, \'CCZ\': 3, \'CSWAP\': 3}\n\n\ndef count(path: str) -> dict:\n    stack: list[str] = []          # open tag names\n    inst_tof: list[int] = []       # inclusive Toffoli count of each open tag instance\n    cond_stack: list[str] = []     # condition bits currently pushed\n    by_path = collections.Counter()            # full path -> Toffolis\n    by_path_cond = collections.Counter()       # (full path, cond tuple) -> Toffolis\n    inst_hist = collections.defaultdict(collections.Counter)  # tag -> {inclusive tof: n instances}\n    bit_def: dict[str, tuple] = {}             # bit -> definition\n    push_defs = collections.Counter()          # definition shape at each PUSH -> n pushes\n    cur_def: list[tuple] = []                  # definition of each pushed condition\n    reg_bits: dict[str, str] = {}              # bit -> \'Ename[idx]\'\n    reg_members = collections.defaultdict(list)\n    pending_reg: dict[str, list] = collections.defaultdict(list)\n    op_counts = collections.Counter()\n\n    def describe(d: tuple) -> dict:\n        # Shape of a condition-bit definition: which registers feed the OR, and\n        # how many bits of each (register names collapsed to their letter prefix).\n        if d[0] != \'or_of\':\n            return {\'kind\': d[0]}\n        regs = collections.Counter(reg_bits.get(b, b).split(\'[\')[0] for b in d[1])\n        prefixes = collections.Counter(\'\'.join(ch for ch in r if not ch.isdigit()) for r in regs)\n        return {\'kind\': \'or_of\', \'n_sources\': len(d[1]), \'n_registers\': len(regs),\n                \'bits_per_register\': sorted(set(regs.values())),\n                \'register_prefixes\': dict(prefixes)}\n\n    total_tof = 0\n    cond_tof = 0\n    n_lines = 0\n\n    with open(path, \'r\', encoding=\'utf-8\') as f:\n        for line in f:\n            n_lines += 1\n            if not line or line[0] == \'#\':\n                continue\n            parts = line.split()\n            if not parts:\n                continue\n            op = parts[0]\n            op_counts[op] += 1\n            if op == \'INFO_TAG\':\n                tag = line.split(\'"\', 2)[1]\n                if tag.startswith(\'@enter:\'):\n                    stack.append(tag[7:])\n                    inst_tof.append(0)\n                elif tag.startswith(\'@exit:\'):\n                    name = tag[6:]\n                    if not stack or stack[-1] != name:\n                        raise ValueError(f\'line {n_lines}: exit {name} does not match {stack[-1:]}\')\n                    stack.pop()\n                    t = inst_tof.pop()\n                    inst_hist[name][t] += 1\n                continue\n            if op in TOFFOLI_LIKE:\n                args = parts[1:]\n                inline = None\n                if \'if\' in args:\n                    k = args.index(\'if\')\n                    inline = args[k + 1:]\n                    args = args[:k]\n                n = len(args) // TOFFOLI_LIKE[op]\n                total_tof += n\n                for i in range(len(inst_tof)):\n                    inst_tof[i] += n\n                key = \'/\'.join(stack)\n                by_path[key] += n\n                conds = tuple(cond_stack) + (tuple(inline) if inline else ())\n                if conds:\n                    cond_tof += n\n                    sig = json.dumps([describe(d) for d in cur_def]\n                                     + [{\'kind\': \'inline\', \'bits\': inline}] * bool(inline),\n                                     sort_keys=True)\n                    by_path_cond[(key, sig)] += n\n                continue\n            if op == \'PUSH_CONDITION\':\n                bit = parts[2]\n                cond_stack.append(bit)\n                d = bit_def.get(bit, (\'undefined\',))\n                cur_def.append(d)\n                push_defs[json.dumps(describe(d), sort_keys=True)] += 1\n                continue\n            if op == \'POP_CONDITION\':\n                cond_stack.pop()\n                cur_def.pop()\n                continue\n            if op == \'BIT_STORE0\':\n                for b in parts[1:]:\n                    if b == \'if\':\n                        break\n                    bit_def[b] = (\'store0\',)\n                continue\n            if op == \'BIT_STORE1\':\n                if \'if\' in parts:\n                    k = parts.index(\'if\')\n                    tgts, srcs = parts[1:k], parts[k + 1:]\n                else:\n                    tgts, srcs = parts[1:], []\n                for b in tgts:\n                    prev = bit_def.get(b, (\'store0\',))\n                    if prev[0] == \'or_of\':\n                        bit_def[b] = (\'or_of\', prev[1] + tuple(srcs))\n                    elif srcs:\n                        bit_def[b] = (\'or_of\', tuple(srcs))\n                    else:\n                        bit_def[b] = (\'store1\',)\n                continue\n            if op == \'HMR\':\n                # HMR q b: X-basis measurement into bit b (random outcome).\n                for b in parts[1:]:\n                    if b.startswith(\'b\'):\n                        bit_def[b] = (\'measured\',)\n                continue\n            if op == \'APPEND_TO_REGISTER\':\n                pending_reg[parts[2]].append(parts[1])\n                continue\n            if op == \'REGISTER\':\n                rid = parts[1]\n                name = line.split(\'"\')[1] if \'"\' in line else rid\n                for i, b in enumerate(pending_reg.get(rid, [])):\n                    reg_bits[b] = f\'{name}[{i}]\'\n                continue\n\n    if stack:\n        raise ValueError(f\'unclosed tags at EOF: {stack}\')\n\n    cond_summary = collections.defaultdict(lambda: {\'toffolis\': 0, \'definitions\': collections.Counter()})\n    for (key, sig), n in by_path_cond.items():\n        top = key.split(\'/\')[0] if key else \'\'\n        cond_summary[top][\'toffolis\'] += n\n        cond_summary[top][\'definitions\'][sig] += n\n\n    return {\n        \'file\': path,\n        \'n_lines\': n_lines,\n        \'total_toffoli_like\': total_tof,\n        \'conditioned_toffoli_like\': cond_tof,\n        \'op_counts\': dict(op_counts),\n        \'by_path\': dict(sorted(by_path.items(), key=lambda kv: -kv[1])),\n        \'instance_histograms\': {k: {str(t): c for t, c in sorted(v.items())}\n                                for k, v in sorted(inst_hist.items())},\n        \'conditioned_by_top_mark\': {k: {\'toffolis\': v[\'toffolis\'],\n                                        \'definitions\': dict(v[\'definitions\'])}\n                                    for k, v in cond_summary.items()},\n        \'push_condition_definitions\': dict(push_defs),\n        \'conditioned_by_path\': {f\'{k} | {c}\': n for (k, c), n in\n                                sorted(by_path_cond.items(), key=lambda kv: -kv[1])[:200]},\n    }\n\n\ndef main() -> None:\n    res = count(sys.argv[1])\n    with open(sys.argv[2], \'w\') as f:\n        json.dump(res, f, indent=1)\n    print(json.dumps({k: res[k] for k in (\'n_lines\', \'total_toffoli_like\',\n                                          \'conditioned_toffoli_like\')}))\n\n\nif __name__ == \'__main__\':\n    main()\n'
SEGSIM_SRC = '"""Empirical per-shot Toffoli accounting by tag path, from a .kmx circuit.\n\nThe verifier\'s T is the mean number of Toffoli-like gates that a shot executes. In kickmix,\nclassical control (`PUSH_CONDITION if bK` ... `POP_CONDITION`, or an inline `... if bK`) is\nthe only thing that changes what a shot executes. A Toffoli outside every condition runs\nexactly once in every shot. So the per-shot count of a tag path is its unconditioned static\ncount plus the executed count of its conditioned Toffolis.\n\nThis module streams a .kmx, cuts it into segments, and simulates the segments one after another\non one `km.Simulator(counting_operations=True)`, reading and clearing the counters after each\nsegment. Each outermost conditioned region that holds Toffolis becomes its own segment, and so\ndo runs of consecutive such regions whose Toffolis share one tag path. Everything in between\nbecomes an unconditioned segment.\n\nAttribution:\n- In an unconditioned segment every Toffoli is executed once per shot, so each path gets its\n  static count. The measured count is checked against this.\n- In a conditioned segment the executed Toffolis go to the segment\'s paths in proportion to\n  their static counts. That is exact when the segment has one path, or when it is a single\n  region whose Toffolis all sit directly under its one outer condition (they then run in the\n  same shots). The module reports the executed mass in the remaining segments ("inexact").\n\nUsage as a library:\n    sim = km.Simulator(batch_size=N, counting_operations=True, seed=S)\n    sim.use_same_registers_as(circuit); <write inputs>\n    res = run_segmented(kmx_path, sim)\nThe final simulator state equals that after `sim.do(circuit)`; the caller checks this.\n"""\n\nfrom __future__ import annotations\n\nimport collections\nimport time\n\nTOFFOLI_LIKE = {\'CCX\': 3, \'CCZ\': 3, \'CSWAP\': 3}\nDECL = (\'REGISTER\', \'APPEND_TO_REGISTER\')\n\n\ndef _tof_in_line(parts: list[str]) -> int:\n    args = parts[1:]\n    if \'if\' in args:\n        args = args[:args.index(\'if\')]\n    return len(args) // TOFFOLI_LIKE[parts[0]]\n\n\ndef run_segmented(kmx_path: str, sim, km=None, progress_every_s: float = 60.0) -> dict:\n    if km is None:\n        import kickmix as km\n    stack: list[str] = []\n    depth = 0                      # condition depth\n    run_lines: list[str] = []      # pending unconditioned text\n    run_static = collections.Counter()\n    reg_lines: list[str] = []      # current outermost conditioned region\n    reg_static = collections.Counter()\n    reg_uniform = [True]           # no Toffoli of the region sits under a nested/inline condition\n    cseg_uniform = [True]\n    cseg_lines: list[str] = []     # pending conditioned segment (merged regions)\n    cseg_static = collections.Counter()\n\n    static_uncond = collections.Counter()\n    static_cond = collections.Counter()\n    exec_cond = collections.Counter()      # path -> executed Toffolis summed over shots\n    inexact_exec = 0.0\n    n_seg = {\'uncond\': 0, \'cond\': 0, \'cond_multi_path\': 0}\n    uncond_mismatch = []\n    total_exec = 0\n    shots = sim.batch_size\n    t0 = last = time.time()\n\n    def execute(lines: list[str]) -> int:\n        nonlocal total_exec\n        if not lines:\n            return 0\n        sim.clear_operation_statistics()\n        sim.do(km.Circuit(\'\\n\'.join(lines)))\n        n = int(sim.operation_statistics().num_toffoli_like)\n        total_exec += n\n        return n\n\n    def flush_run() -> None:\n        if not run_lines:\n            return\n        n = execute(run_lines)\n        exp = sum(run_static.values()) * shots\n        if n != exp and len(uncond_mismatch) < 20:\n            uncond_mismatch.append({\'expected\': exp, \'measured\': n})\n        static_uncond.update(run_static)\n        n_seg[\'uncond\'] += 1\n        run_lines.clear()\n        run_static.clear()\n\n    def flush_cseg() -> None:\n        nonlocal inexact_exec\n        if not cseg_lines:\n            return\n        n = execute(cseg_lines)\n        tot = sum(cseg_static.values())\n        for p, s in cseg_static.items():\n            exec_cond[p] += n * s / tot\n        static_cond.update(cseg_static)\n        n_seg[\'cond\'] += 1\n        if len(cseg_static) > 1:\n            n_seg[\'cond_multi_path\'] += 1\n            if not cseg_uniform[0]:\n                inexact_exec += n\n        cseg_lines.clear()\n        cseg_static.clear()\n        cseg_uniform[0] = True\n\n    def close_region() -> None:\n        # An outermost conditioned region (or one inline-conditioned line) has ended.\n        if not reg_static:\n            run_lines.extend(reg_lines)           # no Toffolis: keep it in the run\n        else:\n            mergeable = (cseg_lines and not run_static and len(reg_static) == 1\n                         and len(cseg_static) == 1 and set(reg_static) == set(cseg_static))\n            if not mergeable:\n                flush_cseg()\n                flush_run()\n            elif run_lines:                       # Toffoli-free text between merged regions\n                cseg_lines.extend(run_lines)\n                run_lines.clear()\n            # A lone uniform region is exact even with several paths (one condition gates all).\n            # Merged regions are single-path by construction.\n            cseg_uniform[0] = (not cseg_lines) and reg_uniform[0] or (cseg_uniform[0] and len(reg_static) == 1)\n            cseg_lines.extend(reg_lines)\n            cseg_static.update(reg_static)\n        reg_lines.clear()\n        reg_static.clear()\n        reg_uniform[0] = True\n\n    with open(kmx_path, \'r\', encoding=\'utf-8\') as f:\n        for line in f:\n            s = line.rstrip(\'\\n\')\n            if not s or s[0] == \'#\':\n                continue\n            parts = s.split()\n            op = parts[0]\n            if op in DECL:\n                continue\n            if op == \'INFO_TAG\':\n                tag = s.split(\'"\', 2)[1]\n                if tag.startswith(\'@enter:\'):\n                    stack.append(tag[7:])\n                elif tag.startswith(\'@exit:\'):\n                    stack.pop()\n                (reg_lines if depth else run_lines).append(s)\n                continue\n            if op == \'PUSH_CONDITION\':\n                depth += 1\n                reg_lines.append(s)\n                continue\n            if op == \'POP_CONDITION\':\n                depth -= 1\n                reg_lines.append(s)\n                if depth == 0:\n                    close_region()\n                continue\n            if op in TOFFOLI_LIKE:\n                n = _tof_in_line(parts)\n                path = \'/\'.join(stack)\n                inline = \'if\' in parts\n                if depth:\n                    reg_lines.append(s)\n                    reg_static[path] += n\n                    if depth > 1 or inline:\n                        reg_uniform[0] = False\n                elif inline:\n                    reg_lines.append(s)\n                    reg_static[path] += n\n                    close_region()\n                else:\n                    run_lines.append(s)\n                    run_static[path] += n\n            else:\n                (reg_lines if depth else run_lines).append(s)\n            # If a cond segment is pending and unconditioned Toffolis arrive, flush order matters:\n            # the cond segment must execute before the run that follows it.\n            if run_static and cseg_lines:\n                pending = run_lines[:]\n                pstatic = run_static.copy()\n                run_lines.clear()\n                run_static.clear()\n                flush_cseg()\n                run_lines.extend(pending)\n                run_static.update(pstatic)\n            if time.time() - last > progress_every_s:\n                last = time.time()\n                print(f\'  segsim {time.time() - t0:.0f}s segments {n_seg}\', flush=True)\n    if depth:\n        raise ValueError(\'unbalanced conditions at EOF\')\n    flush_cseg()\n    flush_run()\n\n    paths = set(static_uncond) | set(static_cond)\n    per_shot = {p: static_uncond[p] + exec_cond[p] / shots for p in paths}\n    return {\n        \'shots\': shots,\n        \'segments\': n_seg,\n        \'wall_s\': round(time.time() - t0, 1),\n        \'total_executed_toffoli\': total_exec,\n        \'per_shot_total\': total_exec / shots,\n        \'inexact_executed_fraction\': inexact_exec / total_exec if total_exec else 0.0,\n        \'uncond_segment_mismatches\': uncond_mismatch,\n        \'static_uncond_by_path\': dict(static_uncond),\n        \'static_cond_by_path\': dict(static_cond),\n        \'per_shot_by_path\': dict(sorted(per_shot.items(), key=lambda kv: -kv[1])),\n    }\n'


def load_src(name: str, src: str):
    import types
    mod = types.ModuleType(name)
    exec(compile(src, f'{name}.py', 'exec'), mod.__dict__)
    return mod


def find_data_root() -> Path:
    marker = Path('verifiers') / 'dqi' / 'verify_submission_dqi.py'
    for dirpath, dirnames, _ in os.walk('/kaggle/input'):
        if (Path(dirpath) / marker).is_file():
            return Path(dirpath)
        if dirpath.count(os.sep) > 6:
            dirnames[:] = []
    raise FileNotFoundError('competition data not found under /kaggle/input')


def find_dataset() -> Path:
    hits = [h for h in glob.glob('/kaggle/input/**/QCC_RELEASE_MANIFEST.json', recursive=True)
            if Path(h).with_name('dqi.kmb.xz').is_file()]
    if len(hits) != 1:
        raise FileNotFoundError(f'expected one release dataset, found {hits}')
    return Path(hits[0]).parent


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(1 << 22), b''):
            h.update(chunk)
    return h.hexdigest()


def canonical_sha(circuit) -> str:
    buf = io.BytesIO()
    circuit.to_file(buf, format='kmb')
    return hashlib.sha256(buf.getvalue()).hexdigest()


def stats_dict(circuit) -> dict:
    s = circuit.operation_statistics()
    return {'num_qubits': circuit.num_qubits, 'num_bits': circuit.num_bits,
            'num_registers': circuit.num_registers,
            'num_toffoli_like': s.num_toffoli_like, 'num_t_like': s.num_t_like,
            'num_instructions': s.num_instructions, 'op_counts': dict(s)}


def step_prepare(data: Path) -> None:
    ds = find_dataset()
    xz = ds / 'dqi.kmb.xz'
    manifest = json.loads((ds / 'QCC_RELEASE_MANIFEST.json').read_text())
    entry = next(e for e in manifest['files'] if e['file'] == 'dqi.kmb')
    info = {'dataset_dir': str(ds), 'xz_sha256': sha256_file(xz), 'xz_bytes': xz.stat().st_size,
            'manifest_portfolio': manifest.get('portfolio'), 'manifest_dqi_sha256': entry['sha256'],
            'manifest_sha256': sha256_file(ds / 'QCC_RELEASE_MANIFEST.json'),
            'dataset_listing': sorted(os.listdir(ds))}
    if info['xz_sha256'] != EXPECTED_XZ_SHA:
        raise SystemExit(f'dataset dqi.kmb.xz differs from the local download: {info}')
    TMP.mkdir(parents=True, exist_ok=True)
    with lzma.open(xz) as fi, open(KMB, 'wb') as fo:
        shutil.copyfileobj(fi, fo, 1 << 22)
    info['kmb_sha256'] = sha256_file(KMB)
    info['kmb_bytes'] = KMB.stat().st_size
    if info['kmb_sha256'] != EXPECTED_KMB_SHA or info['kmb_sha256'] != entry['sha256']:
        raise SystemExit(f'decompressed dqi.kmb hash mismatch: {info}')
    (OUT / 'prepare.json').write_text(json.dumps(info, indent=1))
    print(json.dumps({k: info[k] for k in ('xz_sha256', 'kmb_sha256', 'manifest_portfolio')}))


def write_excerpts(kmx: Path, outdir: Path) -> dict:
    """First instance of every tag name (nesting-aware, capped), plus the first instruction lines."""
    outdir.mkdir(parents=True, exist_ok=True)
    seen: set[str] = set()
    open_caps: list[list] = []    # [name, depth_at_enter, lines]
    head: list[str] = []
    depth = 0
    index = {}
    with open(kmx, encoding='utf-8') as f:
        for line in f:
            op = line.split(' ', 1)[0].rstrip('\n')
            if op in ('REGISTER', 'APPEND_TO_REGISTER'):
                continue
            if len(head) < EXCERPT_MAX_LINES:
                head.append(line)
            is_tag = op == 'INFO_TAG'
            if is_tag:
                tag = line.split('"', 2)[1]
                if tag.startswith('@enter:'):
                    name = tag[7:]
                    depth += 1
                    if name not in seen:
                        seen.add(name)
                        open_caps.append([name, depth, []])
            for cap in open_caps:
                if len(cap[2]) < EXCERPT_MAX_LINES:
                    cap[2].append(line)
            if is_tag and tag.startswith('@exit:'):
                done = [c for c in open_caps if c[1] == depth]
                for c in done:
                    fn = ''.join(ch if ch.isalnum() or ch in '-_' else '_' for ch in c[0])[:80]
                    (outdir / f'{fn}.kmx').write_text(''.join(c[2]))
                    index[c[0]] = {'file': f'{fn}.kmx', 'lines': len(c[2])}
                    open_caps.remove(c)
                depth -= 1
    (outdir / 'head.kmx').write_text(''.join(head))
    return index


def step_count(data: Path) -> None:
    import kickmix as km
    counter = load_src('kmx_tag_count', COUNTER_SRC)
    t0 = time.time()
    c = km.Circuit.from_file(str(KMB))
    load_s = time.time() - t0
    info = {'load_s': round(load_s, 1), 'canonical_sha256': canonical_sha(c), **stats_dict(c),
            'reaction_depth': c.reaction_depth()}
    regs = c.register_data
    info['register_names_sample'] = sorted(regs)[:5] + sorted(regs)[-5:]
    t1 = time.time()
    c.to_file(str(KMX), format='kmx')
    info['kmx_write_s'] = round(time.time() - t1, 1)
    info['kmx_bytes'] = KMX.stat().st_size
    del c
    t2 = time.time()
    res = counter.count(str(KMX))
    res['count_s'] = round(time.time() - t2, 1)
    res['circuit_info'] = info
    res['counter_total_matches_stats'] = res['total_toffoli_like'] == info['num_toffoli_like']
    t3 = time.time()
    res['excerpts'] = write_excerpts(KMX, OUT / 'excerpts')
    res['excerpt_s'] = round(time.time() - t3, 1)
    (OUT / 'count.json').write_text(json.dumps(res, indent=1))
    print(json.dumps({'q': info['num_qubits'], 'static_toffoli': info['num_toffoli_like'],
                      'tag_total': res['total_toffoli_like'],
                      'conditioned': res['conditioned_toffoli_like'],
                      'n_tag_names': len(res['instance_histograms'])}))


def step_segsim(data: Path, worker: int) -> None:
    import numpy as np
    import kickmix as km
    sys.path.insert(0, str(data / 'verifiers' / 'dqi'))
    import verify_submission_dqi as v
    seg = load_src('kmx_segment_sim', SEGSIM_SRC)
    c = km.Circuit.from_file(str(KMB))
    mn = os.environ.get('EXP005_SPEC_MN')  # local smoke test only, e.g. '20,6'; unset on Kaggle
    spec = (v.ProblemSpecDQI.benchmark_instance(m=int(mn.split(',')[0]), n=int(mn.split(',')[1]))
            if mn else v.ProblemSpecDQI.benchmark_instance())
    tables = v.FieldTables(km.GF2Field(spec.degree))
    weight_probs = v.optimal_dqi_weights(spec.m, spec.max_errors, spec.degree, spec.r) ** 2
    seed = SEG_SEED0 + worker
    rng = np.random.default_rng(seed)
    syndromes, mbuc, phases = v.sample_shots(spec, tables, rng, SEG_SHOTS, weight_probs)
    syn_q, mbuc_b, anc = v.validate_registers(c, spec)
    syn_a, mbuc_a = km.array(syn_q), km.array(mbuc_b)
    in_syn = v.to_bits(syndromes, spec.degree)

    def fresh():
        sim = km.Simulator(batch_size=SEG_SHOTS, debug_print=False, counting_operations=True, seed=seed)
        sim.use_same_registers_as(c)
        sim.write_across_shots(syn_a, in_syn)
        sim.write_across_shots(mbuc_a, v.to_bits(mbuc, spec.degree))
        return sim

    def check(sim):
        flipped = sim.read_phase_flipped_across_shots()
        diff = sim.read_across_shots(syn_a) ^ in_syn
        junk = sim.read_across_shots(anc) if len(anc) else np.zeros((0, SEG_SHOTS), dtype=bool)
        val = diff.any(axis=0) | junk.any(axis=0)
        ph = (flipped ^ phases) & ~val
        allq = sim.read_across_shots(km.array([km.q(k) for k in range(c.num_qubits)]))
        return int(val.sum()), int(ph.sum()), flipped, allq

    t0 = time.time()
    a = fresh()
    a.do(c)
    full_tof = int(a.operation_statistics().num_toffoli_like)
    va, pa, fa, qa = check(a)
    full_s = time.time() - t0
    del a
    b = fresh()
    res = seg.run_segmented(str(KMX), b, km=km)
    vb, pb, fb, qb = check(b)
    weights = np.bitwise_or.reduce(syndromes != 0, axis=1)
    res.update({'worker': worker, 'seed': seed, 'full_run_s': round(full_s, 1),
                'full_toffoli': full_tof, 'full_value_errors': va, 'full_phase_errors': pa,
                'seg_value_errors': vb, 'seg_phase_errors': pb,
                'phase_equal': bool(np.array_equal(fa, fb)), 'qubits_equal': bool(np.array_equal(qa, qb)),
                'toffoli_equal': full_tof == res['total_executed_toffoli'],
                'shots_with_nonzero_syndrome': int(weights.sum())})
    (OUT / f'segsim_{worker}.json').write_text(json.dumps(res, indent=1))
    print(json.dumps({k: res[k] for k in ('worker', 'toffoli_equal', 'phase_equal', 'qubits_equal',
                                          'full_value_errors', 'full_phase_errors', 'per_shot_total',
                                          'inexact_executed_fraction', 'segments', 'wall_s')}))


def proc_hwm(p) -> int:
    try:
        with open(f'/proc/{p.pid}/status') as f:
            for line in f:
                if line.startswith('VmHWM:'):
                    return int(line.split()[1]) * 1024
    except OSError:
        pass
    return 0


def run_children(jobs: list[tuple[str, list[str]]]) -> list[dict]:
    """Starts all jobs at once; returns one record per job, with peaks sampled over the group."""
    import psutil
    env = dict(os.environ, PYTHONDONTWRITEBYTECODE='1', PYTHONUNBUFFERED='1',
               EXP005_OUT=str(OUT), EXP005_TMP=str(TMP))
    t0 = time.time()
    procs, files = [], []
    for label, cmd in jobs:
        fo = open(OUT / f'{label}.stdout.txt', 'wb')
        fe = open(OUT / f'{label}.stderr.log', 'wb')
        files += [fo, fe]
        procs.append(subprocess.Popen(cmd, stdout=fo, stderr=fe, env=env, cwd=str(OUT)))
    peaks = [{'tree_rss_peak_bytes': 0, 'proc_hwm_peak_bytes': 0} for _ in jobs]
    group = {'sys_used_peak_bytes': 0}
    walls = [None] * len(jobs)
    stop = threading.Event()

    def poll() -> None:
        while not stop.is_set():
            for i, child in enumerate(procs):
                try:
                    root = psutil.Process(child.pid)
                    ps = [root] + root.children(recursive=True)
                except psutil.Error:
                    continue
                rss = 0
                for p in ps:
                    try:
                        rss += p.memory_info().rss
                    except psutil.Error:
                        pass
                    peaks[i]['proc_hwm_peak_bytes'] = max(peaks[i]['proc_hwm_peak_bytes'], proc_hwm(p))
                peaks[i]['tree_rss_peak_bytes'] = max(peaks[i]['tree_rss_peak_bytes'], rss)
            group['sys_used_peak_bytes'] = max(group['sys_used_peak_bytes'], psutil.virtual_memory().used)
            stop.wait(POLL_S)

    th = threading.Thread(target=poll, daemon=True)
    th.start()
    rcs = []
    for i, child in enumerate(procs):
        rcs.append(child.wait())
        walls[i] = round(time.time() - t0, 1)
    stop.set()
    th.join()
    for fh in files:
        fh.close()
    recs = []
    for i, (label, cmd) in enumerate(jobs):
        text = (OUT / f'{label}.stdout.txt').read_text(errors='replace')
        parsed = None
        if '{' in text:
            try:
                parsed = json.loads(text[text.index('{'):])
            except ValueError:
                parsed = None
        rec = {'label': label, 'cmd': cmd, 'returncode': rcs[i], 'wall_s': walls[i], **peaks[i],
               'group_sys_used_peak_bytes': group['sys_used_peak_bytes'], 'output': parsed}
        print(json.dumps({k: rec[k] for k in ('label', 'returncode', 'wall_s', 'proc_hwm_peak_bytes')}),
              flush=True)
        recs.append(rec)
    return recs


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument('--step', default=None)
    ap.add_argument('--worker', type=int, default=0)
    ap.add_argument('--data-root', type=Path, default=None)
    ap.add_argument('--skip-verify', action='store_true')
    args = ap.parse_args()
    data = (args.data_root or find_data_root()).resolve()
    OUT.mkdir(parents=True, exist_ok=True)
    if args.step == 'prepare':
        return step_prepare(data)
    if args.step == 'count':
        return step_count(data)
    if args.step == 'segsim':
        return step_segsim(data, args.worker)

    if ON_KAGGLE:
        subprocess.run([sys.executable, '-m', 'pip', 'install', '-q', KICKMIX_PIN], check=True)
    from importlib.metadata import version
    info = {'platform': platform.platform(), 'python': sys.version, 'cpu_count': os.cpu_count(),
            'kickmix': version('kickmix'), 'numpy': version('numpy'), 'data_root': str(data),
            'verifier_sha256': sha256_file(data / 'verifiers' / 'dqi' / 'verify_submission_dqi.py')}
    me = str(Path(__file__).resolve())
    base = [sys.executable, me, '--data-root', str(data)]
    runs = []
    log = lambda: (OUT / 'runs.json').write_text(json.dumps({'machine': info, 'runs': runs}, indent=1))
    runs += run_children([('prepare', base + ['--step', 'prepare'])])
    log()
    if runs[-1]['returncode'] != 0:
        print('prepare failed', flush=True)
        return
    runs += run_children([('count', base + ['--step', 'count'])])
    log()
    runs += run_children([(f'segsim_{k}', base + ['--step', 'segsim', '--worker', str(k)])
                          for k in range(SEG_WORKERS)])
    log()
    if not args.skip_verify:
        verifier = str(data / 'verifiers' / 'dqi' / 'verify_submission_dqi.py')
        for salt in SALTS:
            runs += run_children([(f'dqi_salt_{salt}', [sys.executable, verifier, str(KMB), '--salt', salt])])
            log()
    print('done', flush=True)


if __name__ == '__main__':
    main()
